create table if not exists public.employees (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, role text not null default 'employee' check (role in ('employee','admin')), created_at timestamptz not null default now());
create table if not exists public.zones (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, sort_order int not null default 0);
create table if not exists public.performance_records (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), employee_name text not null, zone text not null, date date not null default current_date, start_time timestamptz, end_time timestamptz, convert_count int not null default 0 check(convert_count between 0 and 99), p1_lead_count int not null default 0 check(p1_lead_count between 0 and 99), session_recap_count int not null default 0 check(session_recap_count between 0 and 99), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.employees enable row level security; alter table public.zones enable row level security; alter table public.performance_records enable row level security;
create policy "authenticated read employees" on public.employees for select to authenticated using (true); create policy "authenticated read zones" on public.zones for select to authenticated using (true);
create policy "own records read" on public.performance_records for select to authenticated using (user_id=auth.uid()); create policy "own records insert" on public.performance_records for insert to authenticated with check (user_id=auth.uid());
insert into public.employees(name,role) values ('Hansen','admin'),('Alex','employee'),('Jason','employee'),('Amy','employee') on conflict do nothing; insert into public.zones(name,sort_order) values ('iPhone',1),('Mac',2),('iPad',3),('Apple Watch',4) on conflict do nothing;
